import * as React from 'react';
import { styled } from '@mui/material/styles';
// import FormGroup from '@mui/material/FormGroup';
// import FormControlLabel from '@mui/material/FormControlLabel';
import Switch from '@mui/material/Switch';
// import Stack from '@mui/material/Stack';
// import Typography from '@mui/material/Typography';
import { IconButton } from '@mui/material';
//Import Icons
import { IconPower } from '@tabler/icons';

// import { IconPlugConnected } from '@tabler/icons';
import { useState } from 'react';
//theme
import { useTheme } from '@mui/material/styles';

const AntSwitch = styled(Switch)(({ theme }) => ({
  width: 28,
  height: 16,
  padding: 0,
  display: 'flex',
  '&:active': {
    '& .MuiSwitch-thumb': {
      width: 15
    },
    '& .MuiSwitch-switchBase.Mui-checked': {
      transform: 'translateX(9px)'
    }
  },
  '& .MuiSwitch-switchBase': {
    padding: 2,
    '&.Mui-checked': {
      transform: 'translateX(12px)',
      color: '#fff',
      '& + .MuiSwitch-track': {
        opacity: 1,
        backgroundColor: theme.palette.mode === 'dark' ? '#177ddc' : '#1890ff'
      }
    }
  },
  '& .MuiSwitch-thumb': {
    boxShadow: '0 2px 4px 0 rgb(0 35 11 / 20%)',
    width: 12,
    height: 12,
    borderRadius: 6,
    transition: theme.transitions.create(['width'], {
      duration: 200
    })
  },
  '& .MuiSwitch-track': {
    borderRadius: 16 / 2,
    opacity: 1,
    backgroundColor: theme.palette.mode === 'dark' ? 'rgba(255,255,255,.35)' : 'rgba(0,0,0,.25)',
    boxSizing: 'border-box'
  }
}));

/**SEgundo boton de prueba */

/**Fin segundo boton de prueba */

function CustomizedSwitches() {
  const [turnOn, setTurnOn] = useState(false);

  const handleToggle = () => {
    setTurnOn((prevChecked) => !prevChecked);
  };
  const theme = useTheme();
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
      <div style={{ display: 'flex', alignItems: 'center' }}>
        <AntSwitch defaultChecked inputProps={{ 'aria-label': 'ant design' }} checked={turnOn} onChange={handleToggle} />
        <IconButton
          onClick={!turnOn ? handleToggle : 'none'}
          disabled={!turnOn}
          sx={{ color: turnOn ? `${theme.palette.primary.main}` : 'grey' }}
        >
          <IconPower />
        </IconButton>
      </div>
    </div>
  );
}

function SwitchIA() {
  return (
    <>
      <CustomizedSwitches />
    </>
  );
}
export default SwitchIA;
